package com.pharmapack.qms.master; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="packaging_lines") @Getter @Setter @NoArgsConstructor public class PackagingLine { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="line_code",nullable=false,unique=true) String lineCode; @Column(name="line_name",nullable=false) String lineName; String location; String status="AVAILABLE"; }